<a class="back" href="<?= e(url('admin/pedidos')) ?>">← Voltar aos pedidos</a><section class="panel"><h1><?= e($title) ?></h1><form method="post" action="<?= e(url('admin/pedidos/save')) ?>"><?= csrfField() ?><input type="hidden" name="id" value="<?= $id?e($id):'' ?>"><input type="hidden" name="chave" value="<?= e($_SESSION['admin_order_key']) ?>"><label>Cliente<select name="cliente_id" required><option value="">Selecione</option><?php foreach ($clients as $c): ?><option value="<?= e($c['id']) ?>" <?= ($data['cliente_id']??'')==$c['id']?'selected':'' ?>><?= e($c['nome'].' · '.$c['email']) ?></option><?php endforeach; ?></select></label><h2>Itens do pedido</h2><p class="hint">Informe as quantidades desejadas. Zero significa não incluir. O servidor calcula o total.</p><div class="table-wrap"><table><thead><tr><th>Jogo</th><th>Preço</th><th>Estoque</th><th>Quantidade</th></tr></thead><tbody><?php foreach ($games as $g): ?><tr><td><?= e($g['titulo']) ?><br><small><?= e($g['plataforma']) ?></small></td><td><?= money($g['preco']) ?></td><td><?= e($g['estoque']) ?></td><td><input aria-label="Quantidade de <?= e($g['titulo']) ?>" type="number" min="0" max="99" name="itens[<?= e($g['id']) ?>]" value="<?= e($quantities[$g['id']]??0) ?>" required></td></tr><?php endforeach; ?></tbody></table></div><div class="form-actions"><button class="btn">Salvar rascunho ↗</button></div></form></section>
